jQuery(window).on("load", function () {
    setTimeout(function () {
        var $ = jQuery;

        /** ---------------------------
         * Certification → OPEN
         * --------------------------- */
        $("#elementor-tab-title-5171")
            .addClass("elementor-active")
            .attr({
                "aria-expanded": "true",
                "aria-selected": "true"
            });

        $("#elementor-tab-content-5171")
            .addClass("elementor-active")
            .removeAttr("hidden")
            .show();

        /** ---------------------------
         * Degree → CLOSED
         * --------------------------- */
        $("#elementor-tab-title-5152")
            .removeClass("elementor-active")
            .attr({
                "aria-expanded": "false",
                "aria-selected": "false"
            });

        $("#elementor-tab-content-5152")
            .removeClass("elementor-active")
            .attr("hidden", "hidden")
            .hide();

        /** ---------------------------
         * Career Track → CLOSED
         * --------------------------- */
        $("#elementor-tab-title-5173")
            .removeClass("elementor-active")
            .attr({
                "aria-expanded": "false",
                "aria-selected": "false"
            });

        $("#elementor-tab-content-5173")
            .removeClass("elementor-active")
            .attr("hidden", "hidden")
            .hide();

    }, 800); // wait for Elementor to finish init
});

