if (!utmSource.value) utmSource.value = getUrlParameter('utm_source');
if (!utmMedium.value) utmMedium.value = getUrlParameter('utm_medium');
if (!utmCampaign.value) utmCampaign.value = getUrlParameter('utm_campaign');
if (!utmContent.value) utmContent.value = getUrlParameter('utm_content');
if (!utmTerm.value) utmTerm.value = getUrlParameter('utm_term');
if (!utmPlacement.value) utmPlacement.value = getUrlParameter('utm_placement'); // NEW: UTM Placement

