div.script:
jQuery(document).on('click', '#CCISO_Brochure', function(){
    // Delay to ensure form is loaded
    setTimeout(function(){
        jQuery('#input_38_12').val('CCISO_Brochure').trigger('change');
    }, 500);

});

jQuery(document).ready(function(){
    if(window.matchMedia("(min-width: 768px)").matches){
        const roadmapExp = jQuery('#roadmapExp option:first');
        const jobRolesCareers = jQuery('#certificationRoadmap #jobRolesCareers option:first');
        const jobRoles = jQuery('#certificationRoadmap #jobRoles option:first');
        const careersTrack = jQuery('#certificationRoadmap #careersTrack option:first');
        const careersList = jQuery('#certificationRoadmap .careerTrackList .careersList ul li');
        let roadmapExpVal;
        let jobRolesCareersVal;
        let jobRolesVal;
        let careersTrackVal;

        // show certificationRoadmap on page ready
        setTimeout(() => {
            jQuery('#customLoader').fadeOut();
            jQuery('#certificationRoadmap').fadeIn();
            jQuery('#certificationRoadmap').css({'visibility': 'visible'});
        }, 600);

        // set roadmapExp values on change
        jQuery('#roadmapExp').change(function(e){
            e.preventDefault();
            roadmapExpVal = String(jQuery(this).val()).trim();
            // reset dropdowns
            jobRolesCareers ? jQuery(jobRolesCareers).prop('selected', true) : null;
            jobRoles ? jQuery(jobRoles).prop('selected', true) : null;
            careersTrack ? jQuery(careersTrack).prop('selected', true) : null;
            jobRolesCareersVal = null;
            jobRolesVal = null;
            careersTrackVal = null;
            // clear careersList style's
            jQuery(careersList).removeAttr('style');
            jQuery(careersList).trigger('mouseleave');
            jQuery('.hideDropdown, .hideDropdown .jobRoleTitle, .hideDropdown #jobRoles, .hideDropdown .careersTitle, .hideDropdown #careersTrack').hide();

            // check careersList tab if it's active or not
            let tabTitleOne = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title')[0];
            let tabTitleTwo = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title')[1];
            !jQuery(tabTitleOne).hasClass('active') && jQuery(tabTitleOne).click();
            !jQuery(tabTitleTwo).hasClass('active') && jQuery(tabTitleTwo).click();
        });

        // select jobRoles / Careers
        jQuery('#jobRolesCareers').change(function(e){
            e.preventDefault();
            jobRolesCareersVal = String(jQuery(this).val()).trim();
            // clear careersList style's
            jQuery(careersList).removeAttr('style');
            jQuery(careersList).trigger('mouseleave');

            // check careersList tab if it's active or not
            let tabTitleOne = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title')[0];
            let tabTitleTwo = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title')[1];
            !jQuery(tabTitleOne).hasClass('active') && jQuery(tabTitleOne).click();
            !jQuery(tabTitleTwo).hasClass('active') && jQuery(tabTitleTwo).click();

            // check roadmap
            if(roadmapExpVal != null){
                // jobRoles
                jobRolesCareersVal != null && jobRolesCareersVal == 'Job Roles' ?
                    (jQuery('.hideDropdown .careersTitle, .hideDropdown #careersTrack').hide(),
                    jQuery('.hideDropdown, .hideDropdown .jobRoleTitle, .hideDropdown #jobRoles').fadeIn(),
                    jobRoles ? jQuery(jobRoles).prop('selected', true) : null,
                    jobRolesVal = null)
                :   // careersTrack
                    jobRolesCareersVal != null && jobRolesCareersVal == 'Careers' ?
                    (jQuery('.hideDropdown, .hideDropdown .jobRoleTitle, .hideDropdown #jobRoles').hide(),
                    jQuery('.hideDropdown, .hideDropdown .careersTitle, .hideDropdown #careersTrack').fadeIn(),
                    careersTrack ? jQuery(careersTrack).prop('selected', true) : null,
                    careersTrackVal = null)
                :
                    (jQuery('.hideDropdown, .hideDropdown .jobRoleTitle, .hideDropdown #jobRoles, .hideDropdown .careersTitle, .hideDropdown #careersTrack').hide(),
                    jobRoles ? jQuery(jobRoles).prop('selected', true) : null,
                    jobRolesVal = null,
                    careersTrack ? jQuery(careersTrack).prop('selected', true) : null,
                    careersTrackVal = null)
            }else{
                alert('Please select value in Roadmap Experience.');
                jobRolesCareers ? jQuery(jobRolesCareers).prop('selected', true) : null;
                jobRolesCareersVal = null;
            }
        });

        // set jobRoles values on change
        jQuery('#jobRoles').change(function(e){
            e.preventDefault();
            jobRolesVal = String(jQuery(this).val()).trim();
            // reset careersTrack
            jQuery(careersTrack).prop('selected', true);
            // clear careersList style's
            jQuery(careersList).removeAttr('style');
            jQuery(careersList).trigger('mouseleave');

            // check careersList tab if it's active or not
            let tabTitleOne = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title')[0];
            let tabTitleTwo = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title')[1];
            !jQuery(tabTitleOne).hasClass('active') && jQuery(tabTitleOne).click();
            !jQuery(tabTitleTwo).hasClass('active') && jQuery(tabTitleTwo).click();

            // change active courses
            if(roadmapExpVal != null && jobRolesVal != null){
                // check careersList tab if it's active or not
                // !jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title').hasClass('current') && jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title').click();
                setTimeout(() => {
                    jQuery(careersList).each(function(index, element){
                        if(String(jQuery(this).find('span').text().trim()) == jobRolesVal){
                            // jQuery('#certificationRoadmap #ApplyBtn').attr("disabled", true);
                            // jQuery('#certificationRoadmap #ApplyBtn').css({'opacity': '0.5', 'cursor': 'not-allowed'});
                            jQuery(this)[0].scrollIntoView({behavior: 'smooth', block: 'center'});
                            jQuery(this).trigger('mouseenter');
                            // check for 5 years courses
                            setTimeout(() => {
                                jQuery('#certificationRoadmap #certRoadmap .elementor-column:not(.doNotCount)').find('.elementor-element .elementor-flip-box__front:not([style])').length == 0 && (
                                    alert('Courses not available for this role.'),
                                    jQuery(jobRoles).prop('selected', true),
                                    jobRolesVal = null,
                                    jQuery(careersList).removeAttr('style'),
                                    jQuery(careersList).trigger('mouseleave'),
                                    jQuery('html, body').animate({scrollTop: jQuery('#certificationRoadmap').offset().top - 100}, 300));
                            }, 200);
                        }else{
                            jQuery(this).css({'opacity': '0.5'});
                        }
                    });
                }, 300);
            }else{
                alert('Please select value in Roadmap Experience.');
                jobRoles ? jQuery(jobRoles).prop('selected', true) : null;
                jobRolesVal = null;
            }
        });

        // set careersTrack values on change
        jQuery('#careersTrack').change(function(e){
            e.preventDefault();
            careersTrackVal = String(jQuery(this).val()).trim();
            // reset jobRoles
            jQuery(jobRoles).prop('selected', true);
            // clear careersList style's
            jQuery(careersList).removeAttr('style');
            jQuery(careersList).trigger('mouseleave');

            // check careersList tab if it's active or not
            let tabTitleOne = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title')[0];
            let tabTitleTwo = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title')[1];
            !jQuery(tabTitleOne).hasClass('active') && jQuery(tabTitleOne).click();
            !jQuery(tabTitleTwo).hasClass('active') && jQuery(tabTitleTwo).click();

            // change active courses
            if(roadmapExpVal != null && careersTrackVal != null){
                setTimeout(() => {
                    jQuery(careersList).each(function(index, element){
                        if(String(jQuery(this).find('span').text().trim()) == careersTrackVal){
                            // jQuery('#certificationRoadmap #ApplyBtn').attr("disabled", true);
                            // jQuery('#certificationRoadmap #ApplyBtn').css({'opacity': '0.5', 'cursor': 'not-allowed'});
                            jQuery(this)[0].scrollIntoView({behavior: 'smooth', block: 'center'});
                            jQuery(this).trigger('mouseenter');
                            // check for 5 years courses
                            setTimeout(() => {
                                jQuery('#certificationRoadmap #certRoadmap .elementor-column:not(.doNotCount)').find('.elementor-element .elementor-flip-box__front:not([style])').length == 0 && (
                                    alert('Courses not available for this role.'),
                                    jQuery(careersTrack).prop('selected', true),
                                    careersTrackVal = null,
                                    jQuery(careersList).removeAttr('style'),
                                    jQuery(careersList).trigger('mouseleave'),
                                    jQuery('html, body').animate({scrollTop: jQuery('#certificationRoadmap').offset().top - 100}, 300));
                            }, 200);
                        }else{
                            jQuery(this).css({'opacity': '0.5'});
                        }
                    });
                }, 300);
            }else{
                alert('Please select value in Roadmap Experience.');
                careersTrack ? jQuery(careersTrack).prop('selected', true) : null;
                careersTrackVal = null;
            }
        });

        // apply CTA
        jQuery('#ApplyBtn').click(function(e){
            e.preventDefault();
            if(roadmapExpVal != null && jobRolesVal != null){
                jQuery(careersList).each(function(index, element){
                    if(String(jQuery(this).find('span').text().trim()) == jobRolesVal){
                        jQuery('#certificationRoadmap #ApplyBtn').attr("disabled", true);
                        jQuery('#certificationRoadmap #ApplyBtn').css({'opacity': '0.5', 'cursor': 'not-allowed'});
                        jQuery(this)[0].scrollIntoView({behavior: 'smooth', block: 'center'});
                        jQuery(this).trigger('mouseenter');
                    }else{
                        jQuery(this).css({'opacity': '0.5'});
                    }
                });
            }else{
                alert('Please select value in Experience and Career field.');
            }
        });

