// for safari suppport
jQuery(window).on('load', function(){
    setTimeout(() => {
        const acctabTitles = jQuery('#certificationRoadmap .careerTrackList .elementor-accordion .elementor-accordion-item .elementor-tab-title');
        if(!acctabTitles.hasClass('show') || !acctabTitles.hasClass('active') || !acctabTitles.hasClass('elementor-active')){
            acctabTitles.click();
        }
    }, 600);
});

// take hovered li color
function changeBgColor(activeColor){
    let rgbValues;
    let currentColor;
    currentColor = activeColor.css('background-color');
    // convert rgb To Hex
    rgbValues = currentColor.match(/\d+/g).map(Number);
    return `#${rgbValues.map(value => value.toString(16).padStart(2, '0').toUpperCase()).join('')}`;
}

// certRoadmap HoverBox effect
function columnHoverBox(columns, newColor, colElements, descriptionColor, activeBox){
    // let targetedCols = Object.keys(colElements);
    let targetedColElements = Object.entries(colElements);
    let roadmapExp = document.getElementById("roadmapExp").value;

    targetedColElements.forEach(([index, elements]) => {
        // apply blur to all other columns
        // jQuery(columns).not(jQuery(columns).filter(`:eq(${index})`)).find('.elementor-element .elementor-flip-box__front').css({'filter': 'blur(3px)', 'transition': 'all 1s'});

        // apply hide to all other columns
        // jQuery(columns).not(jQuery(columns).filter(`:eq(${index})`)).find('.elementor-element .elementor-flip-box__front').css({'background-color': 'transparent'});

        // Skip this iteration : roadmapExperience
        if((roadmapExp == 1 && index == 1) || (roadmapExp == 2 && index == 1) || (roadmapExp == 2 && index == 2) || (roadmapExp == 3 && index == 1) || (roadmapExp == 3 && index == 2)){
            return;
        }

        if(elements != 'all'){
            // specific box
            // jQuery(columns).filter(`:eq(${index})`).find('.elementor-element').filter(elements.map(index => `:eq(${index})`).join(', ')).find('.elementor-flip-box__back').css({'background-color': newColor, 'transition': 'all 0s', 'opacity': 9});

            jQuery(columns).filter(`:eq(${index})`).find('.elementor-element').filter(elements.map(index => `:eq(${index})`).join(', ')).find('.elementor-flip-box__front').css({'background-color': newColor, 'transition': 'all 0s', 'opacity': 9});

            // add class activeBox
            jQuery(columns).filter(`:eq(${index})`).find('.elementor-element').filter(elements.map(index => `:eq(${index})`).join(', ')).find('.elementor-flip-box__front').addClass(activeBox);
        }else{
            // all box
            // jQuery(columns).filter(`:eq(${index})`).find('.elementor-element .elementor-flip-box__back').css({'background-color': newColor, 'transition': 'all 0s', 'opacity': 9});

            jQuery(columns).filter(`:eq(${index})`).find('.elementor-element .elementor-flip-box__front').css({'background-color': newColor, 'transition': 'all 0s', 'opacity': 9});

            // add class activeBox
            jQuery(columns).filter(`:eq(${index})`).find('.elementor-element .elementor-flip-box__front').addClass(activeBox);
        }
    });

    // Description color
    // if(descriptionColor && descriptionColor.length > 0){
    //     jQuery(columns).find('.elementor-element .elementor-flip-box__back .elementor-flip-box__layer__description').css({'color': descriptionColor, 'font-weight': '500', 'transition': 'all 0s'});
    // }else{
    //     jQuery(columns).find('.elementor-element .elementor-flip-box__back .elementor-flip-box__layer__description').css({'color': '#000000', 'font-weight': '500', 'transition': 'all 0s'});
    // }
}

// mobile view
jQuery(document).ready(function(){
    if(window.matchMedia("(max-width: 768px)").matches){
        const roadmapExp = jQuery('#roadmapExpMob option:first');
        const jobRolesCareers = jQuery('#certificationRoadmapMob #jobRolesCareersMob option:first');
        const jobRoles = jQuery('#certificationRoadmapMob #jobRolesMob option:first');
        const careersTrack = jQuery('#certificationRoadmapMob #careersTrackMob option:first');
        const columns = jQuery('#certificationRoadmapMob .elementor-accordion .elementor-accordion-item');
        const flipBox = jQuery('#certificationRoadmapMob .elementor-accordion .elementor-accordion-item .elementor-tab-content .elementor-section .elementor-column .elementor-element .elementor-flip-box');
        const flipBoxFront = jQuery('#certificationRoadmapMob .elementor-accordion .elementor-accordion-item .elementor-tab-content .elementor-section .elementor-column .elementor-element .elementor-flip-box__front');
        const certMobSelectHeight = document.querySelector('#certificationRoadmapMob .certRoadmapMobSelection').offsetHeight;
        const accordionHeader = jQuery("#certificationRoadmapMob .elementor-accordion .elementor-accordion-item .the7-accordion-header");
        let roadmapExpVal;
        let jobRolesCareersVal;
        let jobRolesVal;
        let careersTrackVal;
        let newColor = "#7e2027"; // active box color

        setTimeout(() => {
            // remove extra or blank P tag from tab-contents
            jQuery("#certificationRoadmapMob .elementor-accordion .elementor-tab-content p").filter(function(){
                return jQuery(this).text().trim() === "";
            }).remove();
        }, 400);

        // set roadmapExp values on change
        jQuery('#roadmapExpMob').change(function(e){
            e.preventDefault();
            roadmapExpVal = String(jQuery(this).val());
            // reset dropdowns
            jobRolesCareers ? jQuery(jobRolesCareers).prop('selected', true) : null;
            jobRoles ? jQuery(jobRoles).prop('selected', true) : null;
            careersTrack ? jQuery(careersTrack).prop('selected', true) : null;
            jobRolesCareersVal = null;
            jobRolesVal = null;
            careersTrackVal = null;
            jQuery('.hideDropdown, .hideDropdown .jobRoleTitleMob, .hideDropdown #jobRolesMob, .hideDropdown .careersTitleMob, .hideDropdown #careersTrackMob').hide();

            // remove active boxes color class
