// certRoadmap HoverBox effect
function columnHoverBoxMob(columns, newColor, colElements, descriptionColor, activeBox){
    // let targetedCols = Object.keys(colElements);
    let targetedColElements = Object.entries(colElements);
    let roadmapExp = parseInt(document.getElementById("roadmapExpMob").value);

    targetedColElements.forEach(([index, elements]) => {
        // apply blur to all other columns
        // jQuery(columns).not(jQuery(columns).filter(`:eq(${index})`)).find('.elementor-element .elementor-flip-box__front').css({'filter': 'blur(3px)', 'transition': 'all 1s'});

        // apply hide to all other columns
        // jQuery(columns).not(jQuery(columns).filter(`:eq(${index})`)).find('.elementor-element .elementor-flip-box__front').css({'background-color': 'transparent'});

        // Skip this iteration : roadmapExperience
        if((roadmapExp == 1 && index == 0) ||
           (roadmapExp == 2 && index == 0) ||
           (roadmapExp == 2 && index == 1) ||
           (roadmapExp == 3 && index == 0) ||
           (roadmapExp == 3 && index == 1) ||
           (roadmapExp == 3 && index == 2) ||
           (roadmapExp == 3 && index == 3)){
            return;
        }

        if(elements != 'all'){
            // specific box
            // jQuery(columns).filter(`:eq(${index})`).find('.elementor-tab-content .elementor-section .elementor-column .elementor-element').filter(elements.map(index => `:eq(${index})`).join(', ')).find('.elementor-flip-box__back').css({'background-color': newColor, 'transition': 'all 0s', 'opacity': 9});

            jQuery(columns).filter(`:eq(${index})`).find('.elementor-tab-content .elementor-section .elementor-column .elementor-element').filter(elements.map(index => `:eq(${index})`).join(', ')).find('.elementor-flip-box__front').css({'background-color': newColor, 'transition': 'all 0s', 'opacity': 9});

            // add class activeBox
            jQuery(columns).filter(`:eq(${index})`).find('.elementor-tab-content .elementor-section .elementor-column .elementor-element').filter(elements.map(index => `:eq(${index})`).join(', ')).find('.elementor-flip-box__front').addClass(activeBox);
        }else{
            // all box
            // jQuery(columns).filter(`:eq(${index})`).find('.elementor-tab-content .elementor-section .elementor-column .elementor-element .elementor-flip-box__back').css({'background-color': newColor, 'transition': 'all 0s', 'opacity': 9});

            jQuery(columns).filter(`:eq(${index})`).find('.elementor-tab-content .elementor-section .elementor-column .elementor-element .elementor-flip-box__front').css({'background-color': newColor, 'transition': 'all 0s', 'opacity': 9});

            // add class activeBox
            jQuery(columns).filter(`:eq(${index})`).find('.elementor-tab-content .elementor-section .elementor-column .elementor-element .elementor-flip-box__front').addClass(activeBox);
        }
    });

    // Description color
    // if(descriptionColor && descriptionColor.length > 0){
    //     jQuery(columns).find('.elementor-element .elementor-flip-box__back .elementor-flip-box__layer__description').css({'color': descriptionColor, 'font-weight': '500', 'transition': 'all 0s'});
    // }else{
    //     jQuery(columns).find('.elementor-element .elementor-flip-box__back .elementor-flip-box__layer__description').css({'color': '#000000', 'font-weight': '500', 'transition': 'all 0s'});
    // }
}

// removeFlipBoxClasses
function removeFlipBoxClasses(flipBoxFront){
    jQuery(flipBoxFront).removeClass('csseBox saBox scBox aseBox irBox tiaBox nseBox cseBox dseBox saeBox rtptBox maBox cisoBox btBox dfirBox stBox vaptBox');
}

