input.script:
// Capture current page URL dynamically
document.getElementById('efa_page_url').value = window.location.href;

// Auto-populate UTM parameters from URL
function getUrlParameter(name) {
    name = name.replace(/[\[]/, '\\[').replace(/[\]]/, '\\]');
    var regex = new RegExp('[\\?&]' + name + '=([^&#]*)');
    var results = regex.exec(location.search);
    return results === null ? '' : decodeURIComponent(results[1].replace(/\+/g, ' '));
}

// Populate UTM fields - use URL parameters only if shortcode value is empty
var utmSource = document.getElementById('efa_utm_source');
var utmMedium = document.getElementById('efa_utm_medium');
var utmCampaign = document.getElementById('efa_utm_campaign');
var utmContent = document.getElementById('efa_utm_content');
var utmTerm = document.getElementById('efa_utm_term');
var utmPlacement = document.getElementById('efa_utm_placement'); // NEW: UTM Placement

// Only use URL parameter if shortcode value is empty
if (!utmSource.value) utmSource.value = getUrlParameter('utm_source');
if (!utmMedium.value) utmMedium.value = getUrlParameter('utm_medium');
if (!utmCampaign.value) utmCampaign.value = getUrlParameter('utm_campaign');
