div.script:
		(function($) {
			$(document).ready(function() {
				var modalId = 'custom-modal-72';
				var modal = document.getElementById(modalId);
				var buttons = document.querySelectorAll('.pdp-enquiry a');
				var closeButton = modal.querySelector('.close');
				var inModalBtn = document.querySelectorAll('.open-inquiry-modal');


				function hideFields() {
			$('#field_69_18, #field_69_27, #field_69_25, #field_69_26, #field_69_28, #field_69_29, #field_69_30, #field_69_31, #field_69_32, #field_69_33, #field_69_34, #field_69_35, #field_69_36, #field_69_37, #field_69_38, #field_69_39, #field_69_40, #field_69_41, #field_69_42, #field_69_43, #field_69_44, #field_69_45, #field_69_46').hide();
			}

				function isDesktop() {
    return window.matchMedia('(min-width: 769px)').matches; // Adjust width as needed for your definition of desktop
}

				function showImageBasedOnHiddenField() {
					hideFields();

					var hiddenFieldValue = $("#input_69_12").val();

					switch (hiddenFieldValue) {
							case 'CEH_Brochure':
								if (isDesktop()) $('#field_69_18').show(); // Show CEH image
								break;
							case 'CCISO_Brochure':
								if (isDesktop()) $('#field_69_28').show(); // Show CISO image
								break;
							case 'CPENT_Brochure':
								if (isDesktop()) $('#field_69_26').show(); // Show CPENT image
								break;
							case 'CHFI_Brochure':
								if (isDesktop()) $('#field_69_27').show(); // Show CHFI image
								break;
							case 'CCT_Brochure':
								if (isDesktop()) $('#field_69_25').show(); // Show CCT image
								break;
							case 'ECDE_Brochure':
								if (isDesktop()) $('#field_69_39').show(); // Show ECDE image
//  								if (isDesktop()) jQuery('#field_69_34').show();
								break;
							default:
								hideFields(); // Hide all images if no match
								break;
						}
				}

				$(document).on('gform_post_render gform_validation_failed', function () {
					showImageBasedOnHiddenField();
				});

				// Function to open the modal
				function openModal(modal) {
					modal.style.display = 'flex';
					document.body.classList.add('no-scroll'); // Add class to disable scroll

					// Focus the modal itself to allow tabbing to focusable elements inside
					modal.setAttribute('tabindex', '-1');
					modal.focus();
					hideFields();
				}

				// Function to close the modal
				function closeModal(modal) {
					modal.style.display = 'none';
					document.body.classList.remove('no-scroll'); // Remove class to enable scroll
				}

				// Add click event to buttons to open the modal
				buttons.forEach(function(button) {
					button.addEventListener('click', function(event) {
						event.preventDefault();
						event.stopImmediatePropagation(); // Ensure no other event listeners run
						if (typeof elementorProFrontend !== 'undefined' && elementorProFrontend.modules.lightbox) {
						  elementorProFrontend.modules.lightbox.closeLightbox();
						}
						openModal(modal);

						setTimeout(() => {
							jQuery('[name="input_ip"]').prop("placeholder", "Phone Number");

							//CEH-v13 HOF brochure cta
							if(jQuery(this).parent().parent().attr('id') == 'ceh-brochure-btn-new'){
									if (isDesktop()) jQuery('#field_69_18').show();
								jQuery('#input_69_11').val('/wp-content/uploads/2023/02/CEH_HOF_Report_2023.pdf'); // pdf
							}
