        'encryption': 'Encryption',
        'cpent': 'Pen Testing',
	'cloud-security': 'Cloud Security',
        'ecih': 'Incident Handling',
        'ctia': 'Incident Handling',
        'certified-soc-analyst-csa': 'SOC Analyst',
        'certified-cloud-security-engineer-course': 'Cloud Security',
        'ecde': 'DevSecOps',
        'certified-cybersecurity-technician-certification': 'Cyber Technician',
        'blockchain': 'Blockchain',
        'bdc': 'Blockchain',
        'bfc': 'Blockchain',
        'bblc': 'Blockchain',
        'business-continuity-and-disaster-recovery-training': 'Business Continuity and Disaster Recovery',
        'cscu': 'Fundamentals',
        'ecss': 'Fundamentals',
        'nde': 'Essentials Series',
        'ehe': 'Essentials Series',
        'dfe': 'Essentials Series',
        'dse': 'Essentials Series',
        'sce': 'Essentials Series',
        'cse': 'Essentials Series',
       'iot-security-essentials-ise': 'Essentials Series',
        'tie': 'Essentials Series',
        'case-net': 'Application Security',
        'case-java': 'Application Security',
        'wahs': 'Application Security',
        'soc-analyst': 'SOC Analyst' ,
		'certified-penetration-testing': 'Pen Testing' ,
		'certified-cloud-security': 'Cloud Security',
        'cloud-security-essentials-cse': 'Essentials Series' ,
		'certified-chief-information-security-officer-cciso': 'Executive Management',
        'associate-cciso': 'Executive Management'
    };

    /* =====================================================
       CATEGORY NAME → SLUG MAP
    ===================================================== */
    var categorySlugMap = {
        'Ethical Hacking': 'ethical-hacking',
        'Executive Management': 'executive-management',
        'Computer Forensics': 'computer-forensics',
        'Network Security': 'network-security',
        'Encryption': 'encryption',
        'Pen Testing': 'pen-testing',
        'Incident Handling': 'incident-handling',
        'Cloud Security': 'cloud-security',
        'DevSecOps': 'dev-sec-ops',
        'Cyber Technician': 'cyber-technician',
        'Blockchain': 'blockchain',
        'Business Continuity and Disaster Recovery': 'business-continuity-and-disaster-recovery',
        'Fundamentals': 'fundamentals',
        'Essentials Series': 'essentials',
        'Application Security': 'application-security',
        'SOC Analyst': 'soc-analyst'
    };

    /* =====================================================
       CATEGORY DETECTION (COURSE PAGE)
    ===================================================== */
    var category = null;
    for (var key in categoryMap) {
        if (path.indexOf(key) !== -1) {
            category = categoryMap[key];
            break;
        }
    }

    /* =====================================================
       CATEGORY PAGE FALLBACK
    ===================================================== */
    if (!category && path.startsWith('/train-certify/')) {
        var parts = path.replace(/\/$/, '').split('/');
        if (parts.length === 3) {
            for (var name in categorySlugMap) {
                if (categorySlugMap[name] === parts[2]) {
                    category = name;
                    break;
                }
            }
        }
    }

    /* =====================================================
        ADDED – TRAIN & CERTIFY ROOT PAGE
    ===================================================== */
    if (path.replace(/\/$/, '') === '/train-certify') {
        container.innerHTML =
            'Home' +
            ' > ' +
            'Train & Certify';
        return;
    }

    if (!category || !categorySlugMap[category]) return;

    /* =====================================================
       BUILD BREADCRUMB
    ===================================================== */
    var homeUrl = location.origin;
    var trainUrl = homeUrl + '/train-certify/';
    var categoryUrl = trainUrl + categorySlugMap[category] + '/';
    var cleanTitle = document.title.replace(/[-|].*$/, '').trim();

    var isCategoryPage =
        path.replace(/\/$/, '') ===
        new URL(categoryUrl).pathname.replace(/\/$/, '');

    var html =
        'Home' +
        ' > ' +
        'Train & Certify' +
        ' > ';

    if (isCategoryPage) {
        html += '' + category + '';
    }
        else if(path.includes('certified-security-specialist-ecss') || path.includes('ec-council-certified-encryption-specialist-eces')){
	    html += '' + category + '' +
                ' > ' +
                '' + document.title + '';
}
      else {
        html += '' + category + '' +
                ' > ' +
                '' + cleanTitle + '';
    }

    container.innerHTML = html;

})();

const lazyloadRunObserver = () => {
	const lazyloadBackgrounds = document.querySelectorAll( `.e-con.e-parent:not(.e-lazyloaded)` );
	const lazyloadBackgroundObserver = new IntersectionObserver( ( entries ) => {
		entries.forEach( ( entry ) => {
			if ( entry.isIntersecting ) {
				let lazyloadBackground = entry.target;
				if( lazyloadBackground ) {
					lazyloadBackground.classList.add( 'e-lazyloaded' );
				}
				lazyloadBackgroundObserver.unobserve( entry.target );
			}
		});
	}, { rootMargin: '200px 0px 200px 0px' } );
	lazyloadBackgrounds.forEach( ( lazyloadBackground ) => {
		lazyloadBackgroundObserver.observe( lazyloadBackground );
	} );
};
const events = [
	'DOMContentLoaded',
	'elementor/lazyload/observe',
];
events.forEach( ( event ) => {
	document.addEventListener( event, lazyloadRunObserver );
} );

/**

* GF International Phone — Unified v1.3

*

* v1.3 change: Fixed "MutationObserver.observe: Argument 1 is not an object".

*   Root cause: script was wrapped in a plain IIFE (function($){})(jQuery)

*   which executes immediately — before the DOM is parsed. document.body

*   is null at that point, so MutationObserver.observe(null,...) throws.

*   Fix: replaced IIFE with jQuery(document).ready(function($){...}) so

*   the entire script runs only after document.body exists.

*

* v1.2 change: Fixed ITI version mismatch.

*   utilsScript now points to @20.1.0 on jsdelivr (20.1.1 does not exist).

*   Main ITI script tag on the page must also be corrected to @20.1.0.

*   A version mismatch between the main script and utils.js causes

*   isValidNumber() and getValidationError() to silently return wrong

*   results — which is why form validation appeared broken.

* Merges Script A (ITI Initializer + Hidden Field Writer)

* with Script B (v4.0 — Validator + UX Polish)

* into a single conflict-free script.

*

* COUNTRY SOURCE: localStorage ONLY (key: "userCountryData").

* MaxMind GeoIP writes this value separately before this script runs.

* No external API calls (ipapi.co removed entirely).

* If localStorage has no data, ITI falls back to its own default —

* no hardcoded country is forced.

*

* CONFLICT RESOLUTIONS:

*

*  CONFLICT 1 — Dual country sources (ipapi.co vs localStorage)

*    → FIXED: localStorage (MaxMind) is the ONLY source. No async

*      API call, no race condition, no flag flicker.

*

*  CONFLICT 2 — Script A re-init causing infinite .iti nesting

*    → FIXED: initSingleInput() checks for an existing ITI instance

*      before calling window.intlTelInput(). If an instance already

*      exists (from GravityExtra), it is reused — never re-wrapped.

*      The gfp-bound-{uid} guard prevents any second pass.

*

*  CONFLICT 3 — Two countrychange handlers (Script B cleared phone val)

*    → FIXED: Single 'countrychange.gfUnified' handler per input.

*      Does: reflow fix + hidden field update + error clear.

*      Does NOT clear the phone input value.

*

*  CONFLICT 4 — Two submit guards blocking each other

*    → FIXED: Single 'submit.phoneVal' handler per form.

*      Does: write hidden country field FIRST, then validate.

*      If invalid, blocks submit and scrolls to first error.

*

*  CONFLICT 5 — CSS !important fighting reflow fix

*    → FIXED: CSS only targets width/box-sizing. Reflow toggles

*      display on the flag sprite, which is not affected by width.

*/

jQuery(document).ready(function ($) {

  // -------------------------------------------------------

  // 1. Inject CSS (width fix only — no properties that

  //    interfere with the flag reflow trick)

  //    Safe here: document.head and document.body are both

  //    guaranteed to exist inside document.ready.

  // -------------------------------------------------------

  var style = document.createElement('style');

  style.innerHTML = [

    '.iti { width: 100% !important; }',

    '.iti input { width: 100% !important; box-sizing: border-box !important; }'

  ].join(' ');

  document.head.appendChild(style);

  // -------------------------------------------------------

  // 2. Global state

  // -------------------------------------------------------

  var detectedCountryISO = null;   // set once at boot from localStorage

  var observerTimer      = null;

  var initTimer          = null;

  var uidCounter         = 0;

  // -------------------------------------------------------

  // 3. Country name → ISO2 map (lowercase keys, comprehensive)

  // -------------------------------------------------------

  var COUNTRY_NAME_MAP = {

    "afghanistan": "af", "albania": "al", "algeria": "dz", "andorra": "ad",

    "angola": "ao", "argentina": "ar", "armenia": "am", "australia": "au",

    "austria": "at", "azerbaijan": "az", "bahrain": "bh", "bangladesh": "bd",

    "belarus": "by", "belgium": "be", "bolivia": "bo", "bosnia and herzegovina": "ba",

    "botswana": "bw", "brazil": "br", "brunei": "bn", "bulgaria": "bg",

    "cambodia": "kh", "cameroon": "cm", "canada": "ca", "chile": "cl",

    "china": "cn", "colombia": "co", "costa rica": "cr", "croatia": "hr",

    "cuba": "cu", "cyprus": "cy", "czech republic": "cz", "denmark": "dk",

    "dominican republic": "do", "ecuador": "ec", "egypt": "eg", "el salvador": "sv",

    "estonia": "ee", "ethiopia": "et", "finland": "fi", "france": "fr",

    "georgia": "ge", "germany": "de", "ghana": "gh", "greece": "gr",

    "guatemala": "gt", "honduras": "hn", "hong kong": "hk", "hungary": "hu",

    "iceland": "is", "india": "in", "indonesia": "id", "iran": "ir",

    "iraq": "iq", "ireland": "ie", "israel": "il", "italy": "it",

    "jamaica": "jm", "japan": "jp", "jordan": "jo", "kazakhstan": "kz",

    "kenya": "ke", "kuwait": "kw", "kyrgyzstan": "kg", "latvia": "lv",

    "lebanon": "lb", "libya": "ly", "liechtenstein": "li", "lithuania": "lt",

    "luxembourg": "lu", "macau": "mo", "malaysia": "my", "maldives": "mv",

    "malta": "mt", "mexico": "mx", "moldova": "md", "monaco": "mc",

    "mongolia": "mn", "montenegro": "me", "morocco": "ma", "mozambique": "mz",

    "myanmar": "mm", "namibia": "na", "nepal": "np", "netherlands": "nl",

    "new zealand": "nz", "nicaragua": "ni", "nigeria": "ng", "north korea": "kp",

    "north macedonia": "mk", "norway": "no", "oman": "om", "pakistan": "pk",

    "palestine": "ps", "panama": "pa", "paraguay": "py", "peru": "pe",

    "philippines": "ph", "poland": "pl", "portugal": "pt", "qatar": "qa",

    "romania": "ro", "russia": "ru", "russian federation": "ru", "rwanda": "rw",

    "saudi arabia": "sa", "senegal": "sn", "serbia": "rs", "singapore": "sg",

    "slovakia": "sk", "slovenia": "si", "somalia": "so", "south africa": "za",

    "south korea": "kr", "spain": "es", "sri lanka": "lk", "sudan": "sd",

    "sweden": "se", "switzerland": "ch", "syria": "sy", "taiwan": "tw",

    "tajikistan": "tj", "tanzania": "tz", "thailand": "th", "tunisia": "tn",

    "turkey": "tr", "turkmenistan": "tm", "uganda": "ug", "ukraine": "ua",

    "united arab emirates": "ae", "uae": "ae",

    "united kingdom": "gb", "uk": "gb",

    "united states": "us", "usa": "us", "united states of america": "us",

    "uruguay": "uy", "uzbekistan": "uz", "venezuela": "ve", "vietnam": "vn",

    "yemen": "ye", "zambia": "zm", "zimbabwe": "zw"

  };

  // Formal name overrides for Gravity Forms hidden field submission.

  // Keyed by ISO2. ITI's display names differ from formal UN names

  // that some CRMs/backends expect.

  var COUNTRY_FORMAL_NAMES = {

    'vn': 'Viet Nam',

    'tz': 'Tanzania, United Republic of',

    'ps': 'Palestine, State of'

  };

  // -------------------------------------------------------

  // 4. Resolve a country name string → ISO2 code.

  //    Tries static map first, then ITI's own country data.

  // -------------------------------------------------------

  function resolveISOFromName(countryName) {

    if (!countryName) return null;

    var n = countryName.toLowerCase().trim();

    if (COUNTRY_NAME_MAP[n]) return COUNTRY_NAME_MAP[n];

    try {

      var all     = (window.intlTelInputGlobals || {}).getCountryData

                    ? window.intlTelInputGlobals.getCountryData()

                    : [];

      var matched = null;

      // Exact match first

      all.forEach(function (c) {

        if (c.name.toLowerCase().trim() === n) matched = c.iso2.toLowerCase();

      });

      // Partial match fallback

      if (!matched) {

        all.forEach(function (c) {

          if (!matched && (

            c.name.toLowerCase().includes(n) ||

            n.includes(c.name.toLowerCase())

          )) {

            matched = c.iso2.toLowerCase();

          }

        });

      }

      return matched || null;

    } catch (e) { return null; }

  }

  // -------------------------------------------------------

  // 5. Read country ISO2 from localStorage (MaxMind payload).

  //    Supports multiple payload shapes written by different

  //    MaxMind integration plugins.

  // -------------------------------------------------------

  function readCountryFromStorage() {

    try {

      var raw = localStorage.getItem('efa_location_cache');

      if (!raw) return null;

      var data    = JSON.parse(raw);

      var payload = (data && data.success && data.data) ? data.data : data;

      var iso     = null;

      if      (payload.countryCode)  iso = payload.countryCode.toLowerCase();

      else if (payload.country_code) iso = payload.country_code.toLowerCase();

      else if (payload.countryName)  iso = resolveISOFromName(payload.countryName);

      else if (payload.country) {

        iso = payload.country.length === 2

          ? payload.country.toLowerCase()

          : resolveISOFromName(payload.country);

      }

      return iso || null;

    } catch (e) { return null; }

  }

  // -------------------------------------------------------

  // 6. Detect country — reads localStorage ONLY.

  //    Called once synchronously at boot.

  //

  //    MaxMind GeoIP is responsible for writing 'userCountryData'

  //    to localStorage before this script runs. This script never

  //    makes any external API call for geolocation.

  //

  //    If localStorage is empty or unparseable, detectedCountryISO

  //    stays null — ITI will use its own built-in default (usually

  //    auto-detect via the browser, or the first country in its list).

  //    No hardcoded fallback country is forced on the user.

  // -------------------------------------------------------

  function detectCountry() {

    detectedCountryISO = readCountryFromStorage();

    if (!detectedCountryISO) {

      console.log('[GF Phone] No country data found in localStorage (userCountryData). ITI will use its own default.');

    }

  }

  // -------------------------------------------------------

  // 7. Get formal/normalized country name from an ITI instance.

  //    Used when writing to the GF hidden field.

  // -------------------------------------------------------

  function getFormalCountryName(iti) {

    if (!iti) return '';

    var data = iti.getSelectedCountryData();

    var iso  = (data.iso2 || '').toLowerCase();

    return COUNTRY_FORMAL_NAMES[iso] || data.name || '';

  }

  // -------------------------------------------------------

  // 8. Get or create the hidden country field for a phone input.

  //    Field name: {inputId}_country

  //    This is the same naming convention Script A used so

  //    any backend already reading this field keeps working.

  // -------------------------------------------------------

  function getOrCreateHiddenField(phoneInput) {

    var fieldId = $(phoneInput).attr('id');

    if (!fieldId) return null;

    var name    = fieldId + '_country';

    var $hidden = $('input[name="' + name + '"]');

    if (!$hidden.length) {

      $hidden = $('', {

        type  : 'hidden',

        name  : name,

        value : ''

      });

      $(phoneInput).after($hidden);

    }

    return $hidden;

  }

  // -------------------------------------------------------

  // 9. Stable unique key for an input element.

  //    Same input → same key every call.

  //    This is what makes the "already bound" guard reliable.

  // -------------------------------------------------------

  function getInputUID(input) {

    var itiId = $(input).attr('data-intl-tel-input-id');

    if (itiId !== undefined) return 'iti-' + itiId;

    var elId = $(input).attr('id');

    if (elId) return 'el-' + elId;

    var existing = $(input).attr('data-gfp-uid');

    if (existing) return 'gfp-' + existing;

    var newUid = ++uidCounter;

    $(input).attr('data-gfp-uid', newUid);

    return 'gfp-' + newUid;

  }

  // -------------------------------------------------------

  // 10. Show or clear inline validation error

  // -------------------------------------------------------

  function setError(input, message) {

    var $input   = $(input);

    var $wrapper = $input.closest('.iti');

    var $error   = $wrapper.next('.phone-error-msg');

    if (!$error.length) {

      $error = $('', {

        'class': 'phone-error-msg',

        'style': 'color:#c0392b;font-size:0.85em;display:block;margin-top:4px;'

      });

      $wrapper.after($error);

    }

    if (message) {

      $wrapper.css('outline', '1px solid #c0392b');

      $input.css('border-color', '#c0392b');

      $error.text(message).show();

    } else {

      $wrapper.css('outline', '');

      $input.css('border-color', '');

      $error.text('').hide();

    }

  }

  // -------------------------------------------------------

  // 11. Force DOM reflow to clear ghost flag rendering artifact.

  //

  //     Walks ALL .iti ancestor wrappers (GravityExtra creates

  //     its own wrapper on top of ITI's, so there are ≥2).

  //     Only targets width-independent display property so

  //     the CSS width !important rule doesn't interfere.

  // -------------------------------------------------------

  function forceReflowOnFlag(input) {

    $(input).parents('.iti').each(function () {

      var $sprite = $(this).find('> .iti__country-container .iti__flag');

      if (!$sprite.length) return;

      $sprite.css('display', 'none');

      void $sprite[0].offsetWidth;   // synchronous layout flush

      $sprite.css('display', '');

    });

    $(input).closest('.iti').find('.iti__selected-dial-code').css({

      'overflow'   : 'hidden',

      'white-space': 'nowrap'

    });

  }

  // -------------------------------------------------------

  // 12. Input sanitization — strip invalid characters,

  //     handle paste. No hardcoded digit cap.

  // -------------------------------------------------------

  function bindSanitization(input) {

    var $input = $(input);

    $input.off('input.phoneMaxDigits paste.phoneMaxDigits');

    $input.on('input.phoneMaxDigits', function () {

      var val     = $input.val();

      var cleaned = val.replace(/[^\d\s\-\+\(\)]/g, '');

      if (val !== cleaned) {

        var pos = input.selectionStart;

        $input.val(cleaned);

        try { input.setSelectionRange(pos, pos); } catch (e) {}

      }

    });

    $input.on('paste.phoneMaxDigits', function (e) {

      e.preventDefault();

      var pasted  = (e.originalEvent.clipboardData || window.clipboardData).getData('text');

      var cleaned = pasted.replace(/[^\d\+]/g, '');

      $input.val(cleaned);

      try { input.setSelectionRange(cleaned.length, cleaned.length); } catch (e) {}

    });

  }

  // -------------------------------------------------------

  // 13. Validate using ITI's isValidNumber().

  //     Returns true/false and shows/clears inline error.

  // -------------------------------------------------------

  function validatePhoneInput(input) {

    var $input = $(input);

    var iti    = null;

    try {

      iti = window.intlTelInputGlobals

            ? window.intlTelInputGlobals.getInstance(input)

            : null;

    } catch (e) { iti = null; }

    if (!iti) return true;

    var value      = $input.val().trim();

    var digitsOnly = value.replace(/\D/g, '');

    // Empty field

    if (!value || !digitsOnly) {

      if ($input.prop('required') || $input.attr('required') !== undefined) {

        setError(input, 'Phone number is required.');

        return false;

      }

      setError(input, null);

      return true;

    }

    // Too few digits before running expensive ITI check

    if (digitsOnly.length < 4) {

      setError(input, 'Phone number is too short.');

      return false;

    }

    var isValid   = iti.isValidNumber();

    var errorCode = isValid ? null : iti.getValidationError();

    if (!isValid) {

      var msg;

      switch (errorCode) {

        case 1: msg = "This number doesn't match the selected country."; break;

        case 2: msg = 'Phone number is too short.';                      break;

        case 3: msg = 'Phone number is too long.';                       break;

        case 5: msg = 'Invalid phone number length for this region.';    break;

        default: msg = 'Please enter a valid phone number.';

      }

      setError(input, msg);

      return false;

    }

    setError(input, null);

    return true;

  }

  // -------------------------------------------------------

  // 14. Bind validation events

  // -------------------------------------------------------

  function bindValidation(input) {

    var $input = $(input);

    $input.off('blur.phoneVal input.phoneVal keyup.phoneVal countrychange.phoneVal');

    $input.on('blur.phoneVal', function () {

      validatePhoneInput(input);

    });

    $input.on('input.phoneVal keyup.phoneVal', function () {

      // Only re-validate while an error is already visible (avoids

      // showing errors before the user finishes typing)

      var $err = $input.closest('.iti').next('.phone-error-msg');

      if ($err.length && $err.is(':visible')) validatePhoneInput(input);

    });

    $input.on('countrychange.phoneVal', function () {

      if ($input.val().trim()) validatePhoneInput(input);

    });

  }

  // -------------------------------------------------------

  // 15. Bind countrychange — SINGLE unified handler.

  //

  //     Replaces the two conflicting handlers from Script A

  //     and Script B:

  //       ✓ Reflow fix         (from Script B)

  //       ✓ Hidden field write (from Script A)

  //       ✓ Error clear        (from Script B)

  //       ✗ No phone val wipe  (Script B's clearing removed)

  // -------------------------------------------------------

  function bindCountryChange(input, iti) {

    $(input).off('countrychange.gfUnified');

    $(input).on('countrychange.gfUnified', function () {

      // 1. Clear ghost flag rendering artifact

      forceReflowOnFlag(input);

      // 2. Write updated country to hidden GF field

      var $hidden = getOrCreateHiddenField(input);

      if ($hidden) $hidden.val(getFormalCountryName(iti));

      // 3. Clear any stale validation error

      setError(input, null);

      // NOTE: phone value is intentionally NOT cleared here.

    });

  }

  // -------------------------------------------------------

  // 16. Bind form submit guard — SINGLE unified handler.

  //

  //     Stamped on the DOM  element so inline + popup

  //     forms with the same GF form ID are each guarded

  //     independently.

  //

  //     Replaces the two conflicting submit handlers:

  //       ✓ Write hidden field first  (from Script A)

  //       ✓ Validate all phone inputs (from Script B)

  //       ✓ Block + scroll on failure (from Script B)

  // -------------------------------------------------------

  function bindFormSubmit(input, iti) {

    var $form = $(input).closest('form');

    if (!$form.length || $form.data('phone-submit-bound')) return;

    $form.data('phone-submit-bound', true);

    $form.on('submit.phoneVal gform_pre_submission.phoneVal', function (e) {

      // 1. Write final country name to hidden field

      var $hidden = getOrCreateHiddenField(input);

      if ($hidden && iti) $hidden.val(getFormalCountryName(iti));

      // 2. Validate every phone input in this form

      var allValid = true;

      $form.find('.iti__tel-input, input[type="tel"]').each(function () {

        if (!validatePhoneInput(this)) allValid = false;

      });

      // 3. Block submission if any field is invalid

      if (!allValid) {

        e.preventDefault();

        e.stopImmediatePropagation();

        var $first = $form.find('.phone-error-msg:visible').first();

        if ($first.length) {

          $('html, body').animate({ scrollTop: $first.offset().top - 100 }, 300);

        }

      }

    });

  }

  // -------------------------------------------------------

  // 17. Initialize a single phone input — idempotent.

  //

  //     Decision tree:

  //     a) Already bound by this script?  → skip (guard)

  //     b) ITI instance already exists?   → reuse it (GravityExtra

  //        or prior run already initialized it — NEVER re-wrap)

  //     c) No ITI instance + intlTelInput available? → create it

  //     d) No ITI + library missing?      → skip (will retry on

  //        next MutationObserver / gform_post_render fire)

  // -------------------------------------------------------

  function initSingleInput(input) {

    if (!input) return;

    var uid = getInputUID(input);

    if ($(input).data('gfp-bound-' + uid)) return; // already handled

    var iti = null;

    // Check for existing ITI instance first

    try {

      iti = window.intlTelInputGlobals

            ? window.intlTelInputGlobals.getInstance(input)

            : null;

    } catch (e) { iti = null; }

    if (!iti) {

      // No existing instance — create one if possible

      if (!window.intlTelInput) return;            // library not loaded yet

      if ($(input).hasClass('iti__tel-input')) return; // already wrapped, instance missing — skip

      try {

        iti = window.intlTelInput(input, {

          initialCountry  : detectedCountryISO || 'auto',

          utilsScript     : 'https://cdn.jsdelivr.net/npm/intl-tel-input@20.1.0/build/js/utils.js',

          dropdownContainer: document.body

        });

      } catch (e) { return; }

    } else {

      // Existing instance found — just apply detected country

      if (detectedCountryISO) {

        try { iti.setCountry(detectedCountryISO); } catch (e) {}

      }

    }

    if (!iti) return;

    // Mark as bound BEFORE attaching events (prevents race conditions)

    $(input).data('gfp-bound-' + uid, true);

    // Write initial country to hidden field

    var $hidden = getOrCreateHiddenField(input);

    if ($hidden) $hidden.val(getFormalCountryName(iti));

    // Attach all handlers

    bindCountryChange(input, iti);

    bindSanitization(input);

    bindValidation(input);

    bindFormSubmit(input, iti);

  }

  // -------------------------------------------------------

  // 18. Scan all phone inputs on the page.

  //     Targets both ITI-wrapped inputs and plain tel inputs.

  //     Safe to call repeatedly — initSingleInput is idempotent.

  // -------------------------------------------------------

  function initPhoneInputs() {

    $('input[type="tel"]').each(function () {

      initSingleInput(this);

    });

  }

  // -------------------------------------------------------

  // 19. MutationObserver — catches AJAX forms, popups,

  //     multi-step navigation, dynamically injected forms.

  //     300ms debounce gives GravityExtra time to finish

  //     its own ITI initialization before we read instances.

  //

  //     document.body is guaranteed non-null here because this

  //     entire script runs inside jQuery(document).ready().

  //     Previously the script used a plain IIFE which ran before

  //     the DOM was ready, making document.body null and causing:

  //     "MutationObserver.observe: Argument 1 is not an object"

  // -------------------------------------------------------

  var mutationObserver = new MutationObserver(function (mutations) {

    var relevant = mutations.some(function (m) {

      return Array.prototype.some.call(m.addedNodes, function (node) {

        return node.nodeType === 1 && (

          $(node).is('input[type="tel"]')           ||

          $(node).find('input[type="tel"]').length  ||

          $(node).hasClass('iti__tel-input')         ||

          $(node).find('.iti__tel-input').length     ||

          $(node).hasClass('iti')                    ||

          $(node).find('.iti').length

        );

      });

    });

    if (!relevant) return;

    clearTimeout(observerTimer);

    observerTimer = setTimeout(initPhoneInputs, 300);

  });

  mutationObserver.observe(document.body, { childList: true, subtree: true });

  // -------------------------------------------------------

  // 20. Gravity Forms AJAX hooks

  // -------------------------------------------------------

  $(document).on('gform_post_render', function () {

    clearTimeout(initTimer);

    initTimer = setTimeout(initPhoneInputs, 300);

  });

  $(document).on('gform_confirmation_loaded', function () {

    setTimeout(initPhoneInputs, 300);

  });

  // -------------------------------------------------------

  // 21. Global helper — validate all phone inputs in scope

  // -------------------------------------------------------

  window.validateAllPhoneInputs = function ($scope) {

    var $container = $scope || $(document);

    var allValid   = true;

    $container.find('.iti__tel-input, input[type="tel"]').each(function () {

      if (!validatePhoneInput(this)) allValid = false;

    });

    return allValid;

  };

  // -------------------------------------------------------

  // 22. Boot sequence

  //

  //     detectCountry() is now fully synchronous — it reads

  //     localStorage and sets detectedCountryISO immediately.

  //     No async API call, no Promise, no race condition.

  //     initPhoneInputs() always runs with the correct country

  //     already set.

  // -------------------------------------------------------

  detectCountry();

  setTimeout(initPhoneInputs, 300);

}); // end jQuery(document).ready

