jQuery(document).ready(function($) {

    // Function to set phone field country based on MaxMind data
    function setPhoneFieldCountry() {
        // Get country data from localStorage
        const userCountryData = localStorage.getItem('efa_location_cache');

        if (!userCountryData) {
            console.log('No country data found in localStorage');
            return;
        }

        try {
            const countryData = JSON.parse(userCountryData);
            const countryName = countryData.countryName;

            // Map country names to ISO country codes (add more as needed)
            const countryCodeMap = {
    'United States': 'us',
    'United Kingdom': 'gb',
    'Canada': 'ca',
    'Australia': 'au',
    'India': 'in',
    'Germany': 'de',
    'France': 'fr',
    'Spain': 'es',
    'Italy': 'it',
    'Brazil': 'br',
    'Mexico': 'mx',
    'Japan': 'jp',
    'China': 'cn',
    'Russia': 'ru',
    'South Africa': 'za',
    'Netherlands': 'nl',
    'Belgium': 'be',
    'Switzerland': 'ch',
    'Austria': 'at',
    'Sweden': 'se',
    'Norway': 'no',
    'Denmark': 'dk',
    'Finland': 'fi',
    'Poland': 'pl',
    'Portugal': 'pt',
    'Greece': 'gr',
    'Turkey': 'tr',
    'Argentina': 'ar',
    'Chile': 'cl',
    'Colombia': 'co',
    'Peru': 'pe',
    'New Zealand': 'nz',
    'Singapore': 'sg',
    'Malaysia': 'my',
    'Thailand': 'th',
    'Indonesia': 'id',
    'Philippines': 'ph',
    'Vietnam': 'vn',
    'South Korea': 'kr',
    'Pakistan': 'pk',
    'Bangladesh': 'bd',
    'Egypt': 'eg',
    'Nigeria': 'ng',
    'Kenya': 'ke',
    'Israel': 'il',
    'Saudi Arabia': 'sa',
    'United Arab Emirates': 'ae',
};

            const countryCode = countryCodeMap[countryName];

            if (!countryCode) {
                console.log('Country code mapping not found for:', countryName);
                return;
            }

            // Find all international phone fields
            $('.ginput_container_phone input[type="tel"]').each(function() {
                const phoneInput = $(this)[0];

                // Check if intlTelInput is initialized
                if (phoneInput && window.intlTelInputGlobals) {
                    const iti = window.intlTelInputGlobals.getInstance(phoneInput);

                    if (iti) {
                        // Set the country
                        iti.setCountry(countryCode);
                        console.log('Country set to:', countryCode);
                    }
                }
            });

        } catch (error) {
            console.error('Error parsing country data:', error);
        }
    }

    // Wait for Gravity Forms to fully initialize the phone field
    $(document).on('gform_post_render', function(event, form_id, current_page) {
        // Small delay to ensure intlTelInput is fully initialized
        setTimeout(setPhoneFieldCountry, 300);
    });

    // Also try on page load as a fallback
    setTimeout(setPhoneFieldCountry, 500);
});

