// Initialize dataLayer if not already initialized
window.dataLayer = window.dataLayer || [];
// General Event Listener for Buttons and Anchor Tags
document.addEventListener('DOMContentLoaded', function() {
	// Select all elements that have a `data-event` attribute and contain a button or anchor tag
	const buttonWrappers = document.querySelectorAll('[data-event]');
	buttonWrappers.forEach(wrapper => {
		const button = wrapper.querySelector('button, a');
		if (button) {
			button.addEventListener('click', function(event) {
				console.log('Button clicked:', button); // Debugging log
				const data = { event: wrapper.getAttribute('data-event') };
				// Get the clean text content of the clicked button
				const clickText = button.textContent.trim().replace(/\s+/g, ' ');
				data.click_text = clickText;
				// Loop through all data attributes on the wrapper and add them to the data object
				Array.from(wrapper.attributes).forEach(attr => {
					if (attr.name.startsWith('data-') && attr.name !== 'data-event') {
						const key = attr.name.substring(5); // Remove 'data-' prefix
						data[key] = attr.value;
					}
				});
				// Log data to be pushed to dataLayer
				console.log('Data to push to dataLayer:', data);
				if (typeof dataLayer !== 'undefined') {
					dataLayer.push(data);
					console.log('dataLayer after push:', dataLayer);
				} else {
					console.error('dataLayer is not defined');
				}
				// Manually trigger the popup after dataLayer push if needed
				if (button.tagName === 'A' && button.href) {
					const url = button.href;
					if (url.includes('elementor-action')) {
						// Open the Elementor popup
						window.location.href = url;
					}
				}
			});
		}
	});
	// Handle Accordion Click Events
	const accordions = document.querySelectorAll('.elementor-accordion-item');
	accordions.forEach(accordion => {
		accordion.addEventListener('click', function() {
			const parentElement = accordion.closest('[data-event]');
			if (!parentElement) return; // Exit if no parent element with data-event
			const data = {
				event: parentElement.getAttribute('data-event')
			};
			// Get the clean title text content of the clicked accordion title
			const titleElement = accordion.querySelector('.elementor-accordion-title');
			const clickText = titleElement.textContent.trim().replace(/\s+/g, ' ');
			data.click_text = clickText;
			// Add additional data attributes from the parent element
			Array.from(parentElement.attributes).forEach(attr => {
				if (attr.name.startsWith('data-') && attr.name !== 'data-event') {
					const key = attr.name.substring(5); // Remove 'data-' prefix
					data[key] = attr.value;
				}
			});
			if (typeof dataLayer !== 'undefined') {
				dataLayer.push(data);
				console.log('dataLayer', dataLayer);
			} else {
				console.error('dataLayer is not defined');
			}
		});
	});
});

jQuery(document).ready(function($) {
    var lastId,
		topMenu = $(".pdp-sticky-nav .dt-nav-menu-horizontal"),
		topMenuHeight = topMenu.outerHeight() + 15,
		// Adjust the offset value to trigger the active state earlier
		offsetTolerance = 100, // Adjust this value based on your needs
		menuItems = topMenu.find("a"),
		scrollItems = menuItems.map(function(){
		  var item = $($(this).attr("href"));
		  if (item.length) { return item; }
		});
    $(window).scroll(function(){
       var fromTop = $(this).scrollTop() + topMenuHeight + offsetTolerance;

       var cur = scrollItems.map(function(){
         if ($(this).offset().top < fromTop)
           return this;
       });
       cur = cur[cur.length-1];
       var id = cur && cur.length ? cur[0].id : "";
       if (lastId !== id) {
           lastId = id;
           menuItems
             .parent().removeClass("active")
             .end().filter("[href='#"+id+"']").parent().addClass("active");
       }
       // Ensure that the first item is active if no other section is active
       if (!id) {
           $(".pdp-sticky-nav .dt-nav-menu-horizontal .first").addClass("active");
       }
    });
    // Ensure the first item is active on page load
    if (!lastId) {
        $(".pdp-sticky-nav .dt-nav-menu-horizontal .first").addClass("active");
    }
});

(function() {
    "use strict";

    // Configuration
    var EFA_CONFIG = {
        localStorageKey: "efa_location_cache",
        debug: true,
        maxRetries: 10,
        retryDelay: 500
    };

    // Country name to ISO code mapping
    var COUNTRY_MAPPING = {
        "afghanistan": "af", "albania": "al", "algeria": "dz", "andorra": "ad",
        "angola": "ao", "argentina": "ar", "armenia": "am", "australia": "au",
        "austria": "at", "azerbaijan": "az", "bahrain": "bh", "bangladesh": "bd",
        "belarus": "by", "belgium": "be", "bolivia": "bo", "bosnia and herzegovina": "ba",
        "botswana": "bw", "brazil": "br", "brunei": "bn", "bulgaria": "bg",
        "cambodia": "kh", "cameroon": "cm", "canada": "ca", "chile": "cl",
        "china": "cn", "colombia": "co", "costa rica": "cr", "croatia": "hr",
        "cuba": "cu", "cyprus": "cy", "czech republic": "cz", "denmark": "dk",
        "dominican republic": "do", "ecuador": "ec", "egypt": "eg", "el salvador": "sv",
        "estonia": "ee", "ethiopia": "et", "finland": "fi", "france": "fr",
        "georgia": "ge", "germany": "de", "ghana": "gh", "greece": "gr",
        "guatemala": "gt", "honduras": "hn", "hong kong": "hk", "hungary": "hu",
        "iceland": "is", "india": "in", "indonesia": "id", "iran": "ir",
        "iraq": "iq", "ireland": "ie", "israel": "il", "italy": "it",
        "jamaica": "jm", "japan": "jp", "jordan": "jo", "kazakhstan": "kz",
        "kenya": "ke", "kuwait": "kw", "kyrgyzstan": "kg", "latvia": "lv",
        "lebanon": "lb", "libya": "ly", "liechtenstein": "li", "lithuania": "lt",
        "luxembourg": "lu", "macau": "mo", "malaysia": "my", "maldives": "mv",
        "malta": "mt", "mexico": "mx", "moldova": "md", "monaco": "mc",
        "mongolia": "mn", "montenegro": "me", "morocco": "ma", "mozambique": "mz",
        "myanmar": "mm", "burma": "mm", "namibia": "na", "nepal": "np",
        "netherlands": "nl", "holland": "nl", "new zealand": "nz", "nicaragua": "ni",
        "nigeria": "ng", "north korea": "kp", "north macedonia": "mk", "macedonia": "mk",
        "norway": "no", "oman": "om", "pakistan": "pk", "palestine": "ps",
        "panama": "pa", "paraguay": "py", "peru": "pe", "philippines": "ph",
        "poland": "pl", "portugal": "pt", "qatar": "qa", "romania": "ro",
        "russia": "ru", "rwanda": "rw", "saudi arabia": "sa", "senegal": "sn",
        "serbia": "rs", "singapore": "sg", "slovakia": "sk", "slovenia": "si",
        "somalia": "so", "south africa": "za", "south korea": "kr", "korea": "kr",
        "spain": "es", "sri lanka": "lk", "sudan": "sd", "sweden": "se",
        "switzerland": "ch", "syria": "sy", "taiwan": "tw", "tajikistan": "tj",
        "tanzania": "tz", "thailand": "th", "tunisia": "tn", "turkey": "tr",
        "turkmenistan": "tm", "uganda": "ug", "ukraine": "ua", "united arab emirates": "ae",
        "uae": "ae", "united kingdom": "gb", "uk": "gb", "britain": "gb",
        "great britain": "gb", "england": "gb", "scotland": "gb", "wales": "gb",
        "northern ireland": "gb", "united states": "us", "usa": "us", "america": "us",
        "united states of america": "us", "uruguay": "uy", "uzbekistan": "uz",
        "venezuela": "ve", "vietnam": "vn", "yemen": "ye", "zambia": "zm", "zimbabwe": "zw"
    };

    // Debug logging function
    function log(message, data) {
        if (EFA_CONFIG.debug) {
            //console.log("[EFA v2.9.21 - NEW] " + message, data || "");
        }
    }

    // Get country data from localStorage
    function getStoredCountryData() {
        try {
            var stored = localStorage.getItem(EFA_CONFIG.localStorageKey);
            if (stored) {
                var data = JSON.parse(stored);
                log("Found country data:", data.countryName || "Unknown");
                return data;
            }
        } catch (e) {
            log("Error reading localStorage:", e.message);
        }
        return null;
    }

    // Map country name to ISO code
    function getCountryCode(countryName) {
        if (!countryName) return null;

        var normalized = countryName.toLowerCase().trim();
        var code = COUNTRY_MAPPING[normalized];

        if (code) {
            log("Mapped " + countryName + " to " + code.toUpperCase());
            return code;
        }

        log("No mapping found for: " + countryName);
        return null;
    }

    // Set country on ITI instance
    function setITICountry(phoneInput, countryCode) {
        try {
            // Method 1: Try getInstance
            if (window.intlTelInputGlobals) {
                var iti = window.intlTelInputGlobals.getInstance(phoneInput);
                if (iti && typeof iti.setCountry === "function") {
                    iti.setCountry(countryCode);
                    log("Set country via getInstance: " + countryCode.toUpperCase());
                    return iti;
                }
            }

            // Method 2: Try element property
            var iti = phoneInput.iti || phoneInput._iti;
            if (iti && typeof iti.setCountry === "function") {
                iti.setCountry(countryCode);
                log("Set country via element property: " + countryCode.toUpperCase());
                return iti;
            }

            log("No ITI instance found");
            return null;

        } catch (e) {
            log("Error setting country:", e.message);
            return null;
        }
    }

    // Setup validation for country changes
    function setupValidation(phoneInput, itiInstance) {
        if (!itiInstance) return;

        // Listen for country changes
        phoneInput.addEventListener("countrychange", function() {
            var selectedCountry = itiInstance.getSelectedCountryData();
            if (selectedCountry) {
                log("Country changed to: " + selectedCountry.name);

                // Update localStorage with current selection for validation
                try {
                    var currentData = getStoredCountryData() || {};
                    var updatedData = {
                        ip: currentData.ip || "",
                        countryName: currentData.countryName || "",
                        source: currentData.source || "",
                        validationCountry: selectedCountry.name,
                        validationCode: selectedCountry.iso2
                    };
                    localStorage.setItem(EFA_CONFIG.localStorageKey + "_validation", JSON.stringify(updatedData));
                    log("Updated validation localStorage");
                } catch (e) {
                    log("Error updating validation data:", e.message);
                }
            }
        });

        log("Validation setup complete");
    }

    // Process single phone field
    function processPhoneField(phoneInput, countryCode) {
        if (!phoneInput || !countryCode) return false;

        // Skip if recently processed
        var lastProcessed = phoneInput.getAttribute("data-efa-v285-processed");
        if (lastProcessed && (Date.now() - parseInt(lastProcessed)) < 30000) {
            log("Field recently processed, skipping");
            return true;
        }

        log("Processing phone field...");

        // Set country and get ITI instance
        var itiInstance = setITICountry(phoneInput, countryCode);

        if (itiInstance) {
            // Setup validation
            setupValidation(phoneInput, itiInstance);

            // Mark as processed
            phoneInput.setAttribute("data-efa-v285-processed", Date.now().toString());

            log("Phone field processed successfully");
            return true;
        }

        log("Failed to process phone field");
        return false;
    }

    // Find and process all EFA phone fields
    function processAllPhoneFields(countryCode) {
        var selectors = [
            ".efa-form input[type=\"tel\"]",
            ".efa-form .iti__tel-input",
            ".efa-enquiry-form input[type=\"tel\"]",
            "input.efa-intl-tel"
        ];

        var processed = 0;
        var total = 0;

        for (var i = 0; i < selectors.length; i++) {
            var fields = document.querySelectorAll(selectors[i]);

            for (var j = 0; j < fields.length; j++) {
                total++;
                if (processPhoneField(fields[j], countryCode)) {
                    processed++;
                }
            }
        }

        log("Processing complete: " + processed + "/" + total + " fields processed");
        return processed > 0;
    }

    // Main execution function
    function executeCountrySetup() {
        log("Starting EFA country setup...");

        // Get country from localStorage
        var countryData = getStoredCountryData();
        if (!countryData || !countryData.countryName) {
            log("No country data available");
            return false;
        }

        // Map to country code
        var countryCode = getCountryCode(countryData.countryName);
        if (!countryCode) {
            log("Could not map country name");
            return false;
        }

        // Process phone fields
        return processAllPhoneFields(countryCode);
    }

    // Retry mechanism
    function attemptSetup(attempt) {
        if (!attempt) attempt = 1;

        log("--- Attempt " + attempt + "/" + EFA_CONFIG.maxRetries + " ---");

        // Check if ITI is available
        if (!window.intlTelInput && !window.intlTelInputGlobals) {
            log("ITI not ready yet...");
            if (attempt < EFA_CONFIG.maxRetries) {
                setTimeout(function() {
                    attemptSetup(attempt + 1);
                }, EFA_CONFIG.retryDelay);
                return;
            }
            log("ITI never became available");
            return;
        }

        // Execute setup
        if (executeCountrySetup()) {
            log("EFA country setup completed successfully!");
        } else {
            log("Setup completed but no fields were processed");

            // Try again if early attempts
            if (attempt <= 3) {
                setTimeout(function() {
                    attemptSetup(attempt + 1);
                }, EFA_CONFIG.retryDelay);
            }
        }
    }

    // Handle popup forms
    function setupPopupHandler() {
        var observer = new MutationObserver(function(mutations) {
            var efaModalFound = false;

            mutations.forEach(function(mutation) {
                mutation.addedNodes.forEach(function(node) {
                    if (node.nodeType === 1 && node.classList &&
                        (node.classList.contains("efa-modal") ||
                         (node.querySelector && node.querySelector(".efa-modal")))) {
                        efaModalFound = true;
                    }
                });
            });

            if (efaModalFound) {
                log("EFA popup detected");
                setTimeout(function() {
                    attemptSetup(1);
                }, 1000);
            }
        });

        observer.observe(document.body, {
            childList: true,
            subtree: true
        });

        log("Popup handler setup");
    }

    // Initialize everything
    function initialize() {
        log("EFA v2.8.5 Country Auto-Selection Started");

        // Setup popup handler
        setupPopupHandler();

        // Start initial setup
        setTimeout(function() {
            attemptSetup();
        }, 1000);
    }

    // Start when DOM is ready
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initialize);
    } else {
        initialize();
    }

    // Debug helper
    window.EFAv285 = {
        test: function() {
            log("Manual test");
            return executeCountrySetup();
        },

        check: function() {
            var countryData = getStoredCountryData();
            var phoneFields = document.querySelectorAll(".efa-form input[type=\"tel\"], .efa-form .iti__tel-input");

            var result = {
                country: countryData ? countryData.countryName : "None",
                fields: phoneFields.length,
                ready: !!(window.intlTelInputGlobals || window.intlTelInput)
            };

            log("System check:", result);
            return result;
        },

        force: function() {
            log("Force execution");
            executeCountrySetup();
        }
    };

})();

