        const gformWrapperDiv = document.getElementById("gform_wrapper_38");
        if (gformWrapperDiv) {
            const visibilitySpan = document.createElement("span");
            visibilitySpan.id = "gform_visibility_test_38";
            gformWrapperDiv.insertAdjacentElement("afterend", visibilitySpan);
        }
        const visibilityTestDiv = document.getElementById("gform_visibility_test_38");
        let postRenderFired = false;

        function triggerPostRender() {
            if (postRenderFired) {
                return;
            }
            postRenderFired = true;
            jQuery(document).trigger('gform_post_render', [38, 1]);
            gform.utils.trigger({
                event: 'gform/postRender',
                native: false,
                data: {
                    formId: 38,
                    currentPage: 1
                }
            });
            if (visibilityTestDiv) {
                visibilityTestDiv.parentNode.removeChild(visibilityTestDiv);
            }
        }

        function debounce(func, wait, immediate) {
            var timeout;
            return function() {
                var context = this,
                    args = arguments;
                var later = function() {
                    timeout = null;
                    if (!immediate) func.apply(context, args);
                };
                var callNow = immediate && !timeout;
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
                if (callNow) func.apply(context, args);
            };
        }
        const debouncedTriggerPostRender = debounce(function() {
            triggerPostRender();
        }, 200);

        if (visibilityTestDiv && visibilityTestDiv.offsetParent === null) {
            const observer = new MutationObserver((mutations) => {
                mutations.forEach((mutation) => {
                    if (mutation.type === 'attributes' && visibilityTestDiv.offsetParent !== null) {
                        debouncedTriggerPostRender();
                        observer.disconnect();
                    }
                });
            });
            observer.observe(document.body, {
                attributes: true,
                childList: false,
                subtree: true,
                attributeFilter: ['style', 'class'],
            });
        } else {
            triggerPostRender();
        }
    });
    });
}


