(function () {
    var loaded    = false;
    var zdKey     = 'f11242c3-ae26-40dc-80d1-6117c3b21e5e';
    var idleTimer = null;

    function loadZendesk() {
        if (loaded) return;
        loaded = true;

        window.removeEventListener('scroll',     onScroll,  { passive: true });
        window.removeEventListener('mousemove',  onMouse,   { passive: true });
        window.removeEventListener('touchstart', onTouch,   { passive: true });
        window.removeEventListener('keydown',    onKey);
        clearTimeout(idleTimer);

        var s    = document.createElement('script');
        s.id     = 'ze-snippet';
        s.async  = true;
        s.src    = 'https://static.zdassets.com/ekr/snippet.js?key=' + zdKey;
        s.onload = function () {
            // Auto-open if URL contains ?chat=open
            if (window.location.search.indexOf('chat=open') !== -1 && window.zE) {
                zE('messenger', 'open');
            }
        };
        document.head.appendChild(s);
    }

    // Trigger 1: Scroll past 50%
    function onScroll() {
        var pct = (window.scrollY + window.innerHeight) / document.documentElement.scrollHeight;
        if (pct > 0.5) loadZendesk();
    }

    // Trigger 2: Mouse near bottom-right (chat button area)
    function onMouse(e) {
        if (e.clientY > window.innerHeight * 0.75 &&
            e.clientX > window.innerWidth  * 0.75) {
            loadZendesk();
        }
    }

    // Trigger 3: Any touch (mobile)
    function onTouch() { loadZendesk(); }

    // Trigger 4: Any keypress
    function onKey()   { loadZendesk(); }

    // Trigger 5: 8 second idle fallback
    idleTimer = setTimeout(loadZendesk, 8000);

    window.addEventListener('scroll',     onScroll,  { passive: true });
    window.addEventListener('mousemove',  onMouse,   { passive: true });
    window.addEventListener('touchstart', onTouch,   { passive: true });
    window.addEventListener('keydown',    onKey);
})();

(function () {
    function loadCrazyEgg() {
        if (document.getElementById('crazyegg-script')) return;
        var s   = document.createElement('script');
        s.id    = 'crazyegg-script';
        s.async = true;
        s.type  = 'text/javascript';
        s.src   = '//script.crazyegg.com/pages/scripts/0098/8805.js';
        document.head.appendChild(s);
    }

    if (document.readyState === 'complete') {
        setTimeout(loadCrazyEgg, 1000);
    } else {
        window.addEventListener('load', function () {
            setTimeout(loadCrazyEgg, 1000);
        });
    }
})();

